import { Feather } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";
import * as Clipboard from "expo-clipboard";
import React, { Component, ErrorInfo, ReactNode } from "react";
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  StatusBar,
  Platform,
} from "react-native";

import { apiClient } from "../api/client";
import { APP_VERSION } from "../constants/config";
import { navigationRef } from "../navigation/navigationRef";
import { triggerHaptic } from "../utils/haptics";

export interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?:
    | ReactNode
    | ((props: { error: Error | null; resetError: () => void }) => ReactNode);
  onReset?: () => void;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  showDevDetails: boolean;
  copied: boolean;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, State> {
  public state: State = {
    hasError: false,
    error: null,
    errorInfo: null,
    showDevDetails: true,
    copied: false,
  };

  public static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({
      error,
      errorInfo,
    });

    console.error("ErrorBoundary caught an unhandled error:", error, errorInfo);
    this.props.onError?.(error, errorInfo);

    // Automatically report crash to backend for immediate resolution
    try {
      apiClient
        .post("/notifications/client-error/", {
          error_name: error?.name || "Error",
          error_message: error?.message || String(error),
          stack: error?.stack || "",
          component_stack: errorInfo?.componentStack || "",
          platform: Platform.OS,
          app_version: APP_VERSION,
        })
        .catch(() => {});
    } catch {}
  }

  public resetError = () => {
    triggerHaptic("medium");
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      showDevDetails: false,
    });
    this.props.onReset?.();
  };

  public handleRestart = () => {
    triggerHaptic("medium");
    try {
      if (navigationRef.isReady()) {
        navigationRef.reset({
          index: 0,
          routes: [{ name: "Main" }],
        });
      }
    } catch (err) {
      console.warn("ErrorBoundary failed to reset navigation route:", err);
    }

    this.resetError();
  };

  public handleClearCacheAndRestart = async () => {
    triggerHaptic("medium");
    try {
      const keys = [
        "home_data_cache",
        "home_sections_cache",
        "cached_orders_list",
        "offline_cached_orders",
        "welcome_screen_shown",
      ];
      await AsyncStorage.multiRemove(keys);
    } catch (err) {
      console.warn("ErrorBoundary failed to clear cache:", err);
    }

    try {
      if (navigationRef.isReady()) {
        navigationRef.reset({
          index: 0,
          routes: [{ name: "Main" }],
        });
      }
    } catch (err) {
      console.warn("ErrorBoundary failed to reset navigation route:", err);
    }

    this.resetError();
  };

  public toggleDevDetails = () => {
    this.setState((prev) => ({ showDevDetails: !prev.showDevDetails }));
  };

  public handleCopyError = async () => {
    try {
      const parts = [
        `Error: ${this.state.error?.name || "Error"}: ${this.state.error?.message || "Unknown error"}`,
        this.state.error?.stack
          ? `Call Stack:\n${this.state.error.stack}`
          : null,
        this.state.errorInfo?.componentStack
          ? `Component Stack:\n${this.state.errorInfo.componentStack}`
          : null,
      ].filter(Boolean);

      await Clipboard.setStringAsync(parts.join("\n\n"));
      triggerHaptic("success");
      this.setState({ copied: true });
      setTimeout(() => {
        this.setState({ copied: false });
      }, 2500);
    } catch (err) {
      console.warn("Failed to copy error to clipboard:", err);
    }
  };

  public render() {
    if (this.state.hasError) {
      if (typeof this.props.fallback === "function") {
        return this.props.fallback({
          error: this.state.error,
          resetError: this.resetError,
        });
      }

      if (this.props.fallback) {
        return this.props.fallback;
      }

      const isDev = __DEV__;

      return (
        <View
          style={[
            styles.safeArea,
            { paddingTop: StatusBar.currentHeight || 44 },
          ]}
        >
          <StatusBar barStyle="dark-content" backgroundColor="#F8FAFC" />
          <ScrollView
            contentContainerStyle={styles.scrollContent}
            showsVerticalScrollIndicator={false}
          >
            <View style={styles.container}>
              {/* Header Icon Graphic */}
              <View style={styles.iconOuterCircle}>
                <View style={styles.iconInnerCircle}>
                  <Feather name="alert-triangle" size={42} color="#D97706" />
                </View>
              </View>

              {/* Recovery Messaging */}
              <Text style={styles.title}>Oops! Something went wrong</Text>
              <Text style={styles.safeNote}>
                Don't worry, your cart and data are safe.
              </Text>
              <Text style={styles.description}>
                We ran into an unexpected hiccup while displaying this screen.
                Let's get you back on track.
              </Text>

              {/* Real-time Error Summary Box */}
              {Boolean(this.state.error) && (
                <View style={styles.errorAlertBox}>
                  <Feather
                    name="alert-circle"
                    size={16}
                    color="#DC2626"
                    style={{ marginTop: 2 }}
                  />
                  <View style={{ flex: 1, marginLeft: 8 }}>
                    <Text style={styles.errorAlertTitle}>
                      Reason for interruption:
                    </Text>
                    <Text style={styles.errorAlertText} selectable>
                      {this.state.error?.name || "Error"}:{" "}
                      {this.state.error?.message || "Unexpected condition"}
                    </Text>
                  </View>
                </View>
              )}

              {/* Action Buttons */}
              <View style={styles.actionsContainer}>
                <TouchableOpacity
                  style={styles.primaryButton}
                  activeOpacity={0.85}
                  onPress={this.handleRestart}
                >
                  <Feather
                    name="home"
                    size={20}
                    color="#FFFFFF"
                    style={styles.buttonIcon}
                  />
                  <Text style={styles.primaryButtonText}>
                    Restart App / Return Home
                  </Text>
                </TouchableOpacity>

                <TouchableOpacity
                  style={styles.secondaryButton}
                  activeOpacity={0.8}
                  onPress={this.resetError}
                >
                  <Feather
                    name="refresh-cw"
                    size={18}
                    color="#059669"
                    style={styles.buttonIcon}
                  />
                  <Text style={styles.secondaryButtonText}>Try Again</Text>
                </TouchableOpacity>

                <TouchableOpacity
                  style={styles.tertiaryButton}
                  activeOpacity={0.8}
                  onPress={this.handleClearCacheAndRestart}
                >
                  <Feather
                    name="trash-2"
                    size={16}
                    color="#DC2626"
                    style={styles.buttonIcon}
                  />
                  <Text style={styles.tertiaryButtonText}>
                    Clear Local Cache & Return Home
                  </Text>
                </TouchableOpacity>
              </View>

              {/* Error Details / Diagnostics (Collapsible) */}
              {Boolean(this.state.error) && (
                <View style={styles.devSection}>
                  <TouchableOpacity
                    style={styles.devToggle}
                    onPress={this.toggleDevDetails}
                    activeOpacity={0.7}
                  >
                    <Text style={styles.devToggleText}>
                      {this.state.showDevDetails
                        ? "Hide Error Details ▲"
                        : "Show Error Details ▼"}
                    </Text>
                  </TouchableOpacity>

                  {this.state.showDevDetails && (
                    <View style={styles.diagnosticsContainer}>
                      <ScrollView
                        style={styles.devScrollView}
                        nestedScrollEnabled
                      >
                        <Text style={styles.devErrorTitle}>Error Details:</Text>
                        <Text style={styles.devErrorText} selectable>
                          {this.state.error?.name}: {this.state.error?.message}
                        </Text>
                        {this.state.error?.stack && (
                          <>
                            <Text style={styles.devStackTitle}>
                              Call Stack:
                            </Text>
                            <Text style={styles.devStackText} selectable>
                              {this.state.error.stack}
                            </Text>
                          </>
                        )}
                        {this.state.errorInfo?.componentStack && (
                          <>
                            <Text style={styles.devStackTitle}>
                              Component Stack:
                            </Text>
                            <Text style={styles.devStackText} selectable>
                              {this.state.errorInfo.componentStack}
                            </Text>
                          </>
                        )}
                      </ScrollView>

                      <TouchableOpacity
                        style={styles.copyErrorBtn}
                        onPress={this.handleCopyError}
                        activeOpacity={0.8}
                      >
                        <Feather
                          name={this.state.copied ? "check" : "copy"}
                          size={13}
                          color="#059669"
                          style={{ marginRight: 6 }}
                        />
                        <Text style={styles.copyErrorBtnText}>
                          {this.state.copied
                            ? "Copied to Clipboard!"
                            : "Copy Error Details"}
                        </Text>
                      </TouchableOpacity>
                    </View>
                  )}
                </View>
              )}
            </View>
          </ScrollView>
        </View>
      );
    }

    return this.props.children;
  }
}

