export function ForgotPasswordScreen({ navigation }: Props) {
  const { colors, isDark } = useTheme();
  const [email, setEmail] = useState("");
  const [method, setMethod] = useState<"otp" | "link">("link");
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [message, setMessage] = useState("");

  const handleSubmit = async () => {
    if (!email.trim()) {
      Alert.alert("Required Field", "Please enter your email address.");
      return;
    }

    setIsLoading(true);
    setMessage("");
    try {
      const res = await apiClient.post("/auth/password-reset/", {
        email: email.trim(),
        method,
        portal: "customer",
      });
      const msg =
        typeof res.data === "string"
          ? res.data
          : res.data?.message || "Password reset instructions have been sent.";
      setIsSuccess(true);
      setMessage(String(msg));
    } catch (error: any) {
      const errData = error.response?.data;
      const errMsg =
        typeof errData === "string"
          ? errData
          : errData?.error ||
            errData?.detail ||
            errData?.message ||
            "Failed to request password reset. Please try again.";
      Alert.alert("Request Failed", String(errMsg));
    } finally {
      setIsLoading(false);
    }
  };

  const handleOpenEmailApp = async () => {
    try {
      if (Platform.OS === "android") {
        try {
          // Open default email client inbox directly without compose draft
          await IntentLauncher.startActivityAsync(
            "android.intent.action.MAIN",
            {
              category: "android.intent.category.APP_EMAIL",
              flags: 0x10000000,
            },
          );
          return;
        } catch (intentErr) {
          // Fallback: direct Gmail app scheme
          try {
            await Linking.openURL("googlegmail://");
            return;
          } catch (gmailErr) {
            await Linking.openURL("https://mail.google.com");
            return;
          }
        }
      } else if (Platform.OS === "ios") {
        // iOS message:// opens the Mail app inbox directly without compose
        const canOpenMessage = await Linking.canOpenURL("message://");
        if (canOpenMessage) {
          await Linking.openURL("message://");
          return;
        }
      }
      await Linking.openURL("https://mail.google.com");
    } catch (err) {
      Alert.alert(
        "Email App",
        "Please check your email client or webmail for the store message.",
      );
    }
  };

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: colors.background }}>
