import React, { useState, useEffect } from "react";
import {
  View,
  Text,
  TextInput,
  StyleSheet,
  TouchableOpacity,
  Platform,
  Alert,
  ActivityIndicator,
  Image,
} from "react-native";
import { KeyboardAwareScrollView } from "react-native-keyboard-aware-scroll-view";
import { SafeAreaView } from "react-native-safe-area-context";

import { apiClient } from "../../api/client";
import { useAuth } from "../../context/AuthContext";
import { useTheme } from "../../context/ThemeContext";
import type { AuthStackParamList } from "../../navigation/AuthStack";

type Props = {
  navigation: NativeStackNavigationProp<AuthStackParamList, "Signup">;
};

export function SignupScreen({ navigation }: Props) {
  const { colors, isDark } = useTheme();
  const { loginWithGoogle, pendingRedirect, clearPendingRedirect } = useAuth();
  const [form, setForm] = useState({
    first_name: "",
    email: "",
    mobile_number: "",
    password: "",
    confirm_password: "",
    referral_code: "",
  });

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [showReferralInput, setShowReferralInput] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Live password validation criteria
  const pwd = form.password || "";
  const confirmPwd = form.confirm_password || "";

  const hasMinLength = pwd.length >= 8;
  const hasLetters = /[a-zA-Z]/.test(pwd);
  const hasNumbers = /[0-9]/.test(pwd);
  const isNotOnlyNumbers = pwd.length > 0 && !/^\d+$/.test(pwd);
  const hasMix = hasLetters && hasNumbers;
  const isPasswordValid = hasMinLength && hasMix && isNotOnlyNumbers;

  const doPasswordsMatch =
    pwd.length > 0 && confirmPwd.length > 0 && pwd === confirmPwd;
  const isConfirmDirty = confirmPwd.length > 0;

  // Live referral lookup matching web app
  const [checkingReferral, setCheckingReferral] = useState(false);
  const [referralInfo, setReferralInfo] = useState<{
    isValid?: boolean;
    name?: string;
    error?: string;
  } | null>(null);

  useEffect(() => {
    const code = form.referral_code.trim();
    if (!code) {
      setReferralInfo(null);
      setCheckingReferral(false);
      return;
    }

    setCheckingReferral(true);
    const abortController = new AbortController();

    const timer = setTimeout(async () => {
      try {
        const res = await apiClient.get(
          `/auth/referral-lookup/?code=${encodeURIComponent(code)}`,
          {
            signal: abortController.signal,
          },
        );
        setReferralInfo({
          isValid: true,
          name: res.data.referrer_name || res.data.name,
        });
      } catch (err: any) {
        if (err.name === "CanceledError" || err.message === "canceled") return;
        setReferralInfo({
          isValid: false,
          error: err.response?.data?.error || "Invalid referral code.",
        });
      } finally {
        if (!abortController.signal.aborted) {
          setCheckingReferral(false);
        }
      }
    }, 500);

    return () => {
      clearTimeout(timer);
      abortController.abort();
    };
  }, [form.referral_code]);

  const handleSignup = async () => {
    if (
      !form.first_name ||
      !form.email ||
      !form.mobile_number ||
      !form.password
    ) {
      Alert.alert("Required Fields", "Please complete all required fields.");
      return;
    }

    const cleanMobile = form.mobile_number.trim().replace(/[^0-9]/g, "");
    const indianMobileRegex = /^[6-9][0-9]{9}$/;
    if (!indianMobileRegex.test(cleanMobile)) {
      Alert.alert(
        "Invalid Mobile Number",
        "Please enter a valid 10-digit Indian mobile number starting with 6, 7, 8, or 9.",
      );
      return;
    }

    if (!hasMinLength) {
      Alert.alert(
        "Password Too Short",
        "Password must be at least 8 characters long.",
      );
      return;
    }

    if (!isNotOnlyNumbers) {
      Alert.alert(
        "Invalid Password",
        "Password cannot be entirely numbers. Please include letters.",
      );
      return;
    }

    if (form.password !== form.confirm_password) {
      Alert.alert(
        "Password Mismatch",
        "Passwords do not match. Please re-enter.",
      );
      return;
    }

    if (referralInfo && referralInfo.isValid === false) {
      Alert.alert(
        "Invalid Referral Code",
        "Please enter a valid referral code or clear the field.",
      );
      return;
    }

    setIsLoading(true);
    try {
      const payload = {
        ...form,
        mobile_number: cleanMobile,
        username: form.email,
      };
      await apiClient.post("/auth/signup/", payload);

      Alert.alert(
        "Registration Successful! 🎉",
        `Your account has been created!\n\nWe sent an activation link to ${form.email}. Please check your inbox and click the link to activate your account before logging in.`,
        [
          {
            text: "Proceed to Login",
            onPress: () => navigation.navigate("Login"),
          },
        ],
      );
    } catch (error: any) {
      const details = error.response?.data;
      let errorMessage = "Unable to create account.";
      if (details) {
        if (typeof details === "string") {
          errorMessage = details;
        } else if (typeof details === "object") {
          const firstKey = Object.keys(details)[0];
          const val = details[firstKey];
          errorMessage = Array.isArray(val) ? val[0] : String(val);
        }
      }
      Alert.alert("Registration Failed", errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const [isGoogleLoading, setIsGoogleLoading] = useState(false);

  const processRedirect = () => {
    if (pendingRedirect) {
      const { screen, tab, params } = pendingRedirect;
      clearPendingRedirect();
      if (tab) {
        (navigation as any).navigate("Main", {
          screen: tab,
          params: { screen, params },
        });
      } else {
        (navigation as any).navigate(screen as any, params);
      }
    } else if (navigation.canGoBack()) {
      navigation.goBack();
    } else {
      (navigation as any).navigate("Main" as any);
    }
  };

  const handleGoogleSignup = async () => {
    try {
      setIsGoogleLoading(true);
      await GoogleSignin.hasPlayServices();
      const response = await GoogleSignin.signIn();
      const idToken =
        (response as any).data?.idToken || (response as any).idToken;
      if (idToken) {
        await loginWithGoogle(idToken);
        processRedirect();
      } else {
        throw new Error("No ID token present!");
      }
    } catch (error: any) {
      console.error("Google Signin Error:", error);
      Alert.alert(
        "Google Sign-In Failed",
        error.message || "Something went wrong.",
      );
    } finally {
      setIsGoogleLoading(false);
    }
  };

  const inputBg = isDark ? "rgba(255, 255, 255, 0.05)" : "#F8FAFC";

  return (
    <SafeAreaView
      style={[styles.safeArea, { backgroundColor: colors.background }]}
    >
      <KeyboardAwareScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}
        bounces={false}
        keyboardShouldPersistTaps="handled"
        keyboardDismissMode="on-drag"
        enableOnAndroid
        extraScrollHeight={20}
      >
        {/* Header Bar */}
        <View style={styles.headerBar}>
          <TouchableOpacity
            style={styles.backButton}
            onPress={() =>
              navigation.canGoBack()
                ? navigation.goBack()
                : navigation.navigate("Login")
            }
            activeOpacity={0.7}
            hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
          >
            <Feather name="arrow-left" color={colors.primary} size={18} />
            <Text style={[styles.backButtonText, { color: colors.primary }]}>
              Back
            </Text>
          </TouchableOpacity>

          <View style={styles.titleRow}>
            <View style={styles.brandRow}>
              <Image
                source={require("../../../assets/narendra-logo-tight.png")}
                style={styles.logoImage}
                resizeMode="contain"
              />
              <Text style={styles.brandTitle}>
                <Text style={[styles.brandSlate, { color: colors.text }]}>
                  Narendra{" "}
                </Text>
                <Text style={styles.brandRed}>Kirana</Text>
              </Text>
            </View>
            <Text style={[styles.title, { color: colors.text }]}>
              Create Account
            </Text>
            <Text style={[styles.subtitle, { color: colors.textSecondary }]}>
              Quick registration for fresh daily grocery delivery
            </Text>
          </View>
        </View>

        {/* Form Card */}
        <View
          style={[
            styles.card,
            { backgroundColor: colors.surface, borderColor: colors.border },
          ]}
        >
          {/* Full Name */}
          <View style={styles.inputGroup}>
            <Text style={[styles.label, { color: colors.text }]}>
              Full Name *
            </Text>
            <View
              style={[
                styles.inputWrapper,
                { backgroundColor: inputBg, borderColor: colors.border },
              ]}
            >
              <Feather
                name="user"
                size={15}
