                )}
                {!checkingReferral && referralInfo?.isValid === false && (
                  <Feather
                    name="alert-circle"
                    size={15}
                    color="#EF4444"
                    style={{ marginRight: 8 }}
                  />
                )}
              </View>
              {referralInfo?.name && (
                <Text style={styles.referralSuccessName}>
                  Referred by {referralInfo.name}
                </Text>
              )}
            </View>
          )}

          {/* Submit Button */}
          <TouchableOpacity
            style={[
              styles.primaryButton,
              { backgroundColor: colors.primary },
              isLoading && styles.primaryButtonDisabled,
            ]}
            onPress={handleSignup}
            disabled={isLoading}
