            placeholderTextColor={colors.textSecondary}
            value={customerNote}
            onChangeText={setCustomerNote}
            multiline
            numberOfLines={3}
          />
        </View>

        {/* Digital Wallet Card with Max Percentage Limit Enforcement */}
        {walletBalance > 0 && (
          <View
            style={[
              styles.walletCard,
              isDark && {
                backgroundColor: colors.surface,
