          >
            <View style={styles.walletLeft}>
              <View
                style={[
                  styles.walletIconBox,
                  isDark && { backgroundColor: colors.inputBg },
                ]}
              >
                <MaterialIcons
                  name="currency-rupee"
                  size={20}
                  color={colors.primary}
                />
              </View>
              <View style={{ flex: 1, paddingRight: 8 }}>
                <Text style={[styles.walletTitle, { color: colors.text }]}>
