          <TouchableOpacity
            style={[
              styles.paymentOptionCard,
              { backgroundColor: colors.inputBg, borderColor: colors.border },
              paymentMethod === "COD" && [
                styles.paymentOptionSelected,
                {
                  borderColor: colors.primary,
                  backgroundColor: isDark
                    ? "rgba(16, 185, 129, 0.1)"
                    : "#F0FDF4",
                },
              ],
            ]}
            onPress={() => setPaymentMethod("COD")}
