import { Feather } from "@expo/vector-icons";
import React, { useState, useEffect, useRef, useCallback } from "react";
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  ActivityIndicator,
  TouchableOpacity,
  RefreshControl,
  Platform,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { apiClient } from "../../api/client";
import { useAuth } from "../../context/AuthContext";
import { useTheme } from "../../context/ThemeContext";
import { AppNavigationProp } from "../../navigation/types";
import {
  getCachedOrdersSync,
  loadCachedOrders,
  saveCachedOrders,
} from "../../services/ordersCache";

export function OrderHistoryScreen({
  navigation,
}: {
  navigation: AppNavigationProp;
}) {
  const { user } = useAuth();
  const { colors, isDark } = useTheme();

  // Instant cache-first retrieval (<50ms)
  const cachedOrders = getCachedOrdersSync();
  const [orders, setOrders] = useState<any[]>(cachedOrders || []);
  const [loading, setLoading] = useState(
    !cachedOrders || cachedOrders.length === 0,
  );
  const [refreshing, setRefreshing] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);

  // Request counter to completely prevent race conditions
  const requestIdRef = useRef(0);
  const hasRenderedOrdersRef = useRef(
    Boolean(cachedOrders && cachedOrders.length > 0),
  );

  useEffect(() => {
    if (user) {
      // If memory cache didn't have orders yet, try loading from disk cache immediately
      if (orders.length === 0) {
        loadCachedOrders().then((cached) => {
          if (cached && cached.length > 0) {
            setOrders((prev) => (prev.length === 0 ? cached : prev));
            hasRenderedOrdersRef.current = true;
            setLoading(false);
          }
        });
      }
      // Silent SWR background fetch
      fetchOrders(1);
    } else {
      setOrders([]);
      hasRenderedOrdersRef.current = false;
      setLoading(false);
    }
  }, [user]);

  const fetchOrders = async (
    pageNum: number,
    isRefresh = false,
    isLoadMore = false,
  ) => {
    if (!user) {
      setLoading(false);
      return;
    }
    if (isLoadMore) {
      if (loadingMore || !hasMore || loading || refreshing) return;
      setLoadingMore(true);
    } else if (isRefresh) {
      setRefreshing(true);
    } else {
      // Never show blocking spinner if cached orders exist or were already rendered
      if (!hasRenderedOrdersRef.current && orders.length === 0) {
        setLoading(true);
      }
    }

    const currentReqId = ++requestIdRef.current;

    try {
      const url = pageNum === 1 ? "/orders/" : `/orders/?page=${pageNum}`;
      const res = await apiClient.get(url);

      // Discard results if a newer request was dispatched while this was in-flight
      if (currentReqId !== requestIdRef.current) return;

      const rawData = res.data;
      const newOrders = Array.isArray(rawData)
        ? rawData
        : rawData?.results || [];

      if (pageNum === 1) {
        setOrders(newOrders);
        hasRenderedOrdersRef.current = newOrders.length > 0;
        saveCachedOrders(newOrders).catch(() => {});
      } else {
        setOrders((prev) => {
          const existingIds = new Set(prev.map((o) => String(o.id)));
          const uniqueNew = newOrders.filter(
            (o: any) => !existingIds.has(String(o.id)),
          );
          return [...prev, ...uniqueNew];
        });
      }

      setHasMore(Boolean(rawData?.next));
      setPage(pageNum);
    } catch (error: any) {
      if (error?.response?.status !== 401) {
        console.error("Error fetching orders:", error);
      }
    } finally {
      if (currentReqId === requestIdRef.current) {
        if (isLoadMore) setLoadingMore(false);
        if (isRefresh) setRefreshing(false);
        setLoading(false);
      }
    }
  };

  const handleRefresh = () => {
    setPage(1);
    fetchOrders(1, true, false);
  };

  const handleLoadMore = () => {
    if (hasMore && !loading && !refreshing && !loadingMore) {
      fetchOrders(page + 1, false, true);
    }
  };

  // Status badges matching web tokens (COMPLETED emerald, REJECTED rose, READY blue, PREPARING amber, NEW indigo)
  const getStatusStyle = (status: string) => {
    if (isDark) {
      switch (status) {
        case "COMPLETED":
          return {
            bg: "rgba(16, 185, 129, 0.15)",
            text: "#34D399",
            border: "rgba(16, 185, 129, 0.3)",
          };
        case "REJECTED":
          return {
            bg: "rgba(244, 63, 94, 0.15)",
            text: "#FB7185",
            border: "rgba(244, 63, 94, 0.3)",
          };
        case "READY":
          return {
            bg: "rgba(59, 130, 246, 0.15)",
            text: "#60A5FA",
            border: "rgba(59, 130, 246, 0.3)",
          };
        case "PREPARING":
          return {
            bg: "rgba(245, 158, 11, 0.15)",
            text: "#FBBF24",
            border: "rgba(245, 158, 11, 0.3)",
          };
        case "NEW":
          return {
            bg: "rgba(99, 102, 241, 0.15)",
            text: "#818CF8",
            border: "rgba(99, 102, 241, 0.3)",
          };
        default:
          return {
            bg: "rgba(148, 163, 184, 0.15)",
            text: "#94A3B8",
            border: "rgba(148, 163, 184, 0.3)",
          };
      }
    }
    switch (status) {
      case "COMPLETED":
        return { bg: "#ECFDF5", text: "#047857", border: "#A7F3D0" }; // emerald
      case "REJECTED":
        return { bg: "#FFF1F2", text: "#BE123C", border: "#FECDD3" }; // rose
      case "READY":
        return { bg: "#EFF6FF", text: "#1D4ED8", border: "#BFDBFE" }; // blue
      case "PREPARING":
        return { bg: "#FFFBEB", text: "#B45309", border: "#FDE68A" }; // amber
      case "NEW":
        return { bg: "#EEF2FF", text: "#4338CA", border: "#C7D2FE" }; // indigo
      default:
        return { bg: "#F8FAFC", text: "#475569", border: "#E2E8F0" }; // slate
    }
  };

  const formatDate = (dateString: string) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return dateString;
    }
  };

  const handleBack = () => {
    if (navigation.canGoBack()) {
      if (navigation.canGoBack()) {
        navigation.goBack();
      } else {
        navigation.navigate("Main");
      }
    } else {
      navigation.navigate("HomeTab");
    }
  };

  const renderOrderItem = useCallback(
    ({ item }: { item: any }) => {
      const statusStyle = getStatusStyle(item.status);
      const totalFormatted = (
        parseFloat(String(item?.total_amount || 0)) || 0
      ).toFixed(2);
      const itemCount = item.items?.length || 0;

      return (
        <View
          style={[
            styles.orderCard,
            { backgroundColor: colors.surface, borderColor: colors.border },
          ]}
        >
          <TouchableOpacity
            activeOpacity={0.7}
            onPress={() =>
              navigation.navigate("OrderTrackingScreen", {
                orderId: item.id,
                initialOrder: item,
              })
            }
          >
            <View style={styles.cardHeader}>
              <View>
                <Text style={[styles.orderId, { color: colors.text }]}>
                  #{item.id}
                </Text>
                <Text
                  style={[styles.orderDate, { color: colors.textSecondary }]}
                >
                  {formatDate(item.created_at)}
                </Text>
              </View>
              <View
                style={[
                  styles.statusBadge,
                  {
                    backgroundColor: statusStyle.bg,
                    borderColor: statusStyle.border,
                  },
                ]}
              >
                <Text style={[styles.statusText, { color: statusStyle.text }]}>
                  {item.status}
                </Text>
              </View>
            </View>

            <View
              style={[styles.divider, { backgroundColor: colors.border }]}
            />

            <View style={styles.cardFooterRow}>
