              <View style={styles.completedActionsRow}>
                <TouchableOpacity
                  style={[
                    styles.detailsBtn,
                    {
                      backgroundColor: isDark ? colors.background : "#F8FAFC",
                      borderColor: colors.border,
                    },
                  ]}
                  onPress={() =>
                    navigation.navigate("OrderTrackingScreen", {
                      orderId: item.id,
                      initialOrder: item,
                    })
