          <Text
            style={[styles.headerSubtitle, { color: colors.textSecondary }]}
          >
            Track and review your past purchases.
          </Text>
        </View>
        <View style={styles.guestStateContainer}>
          <View
            style={[
              styles.guestIconBox,
              {
                backgroundColor: isDark ? "rgba(5, 150, 105, 0.15)" : "#ECFDF5",
