import { Feather } from "@expo/vector-icons";
import React, { useEffect, useRef } from "react";
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  BackHandler,
  Animated,
  Easing,
  Platform,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { useTheme } from "../../context/ThemeContext";
import { AppNavigationProp } from "../../navigation/types";
import { triggerHaptic } from "../../utils/haptics";

const USE_NATIVE_DRIVER = Platform.OS !== "web";

type Props = {
  navigation: AppNavigationProp;
  route: any;
};

export function OrderSuccessScreen({ navigation, route }: Props) {
  const { colors, isDark } = useTheme();
  const { orderId } = route.params || {};
  const isNavigatingRef = useRef(false);

  // Celebration pop animation
  const scaleAnim = useRef(new Animated.Value(0.3)).current;
  const haloAnim = useRef(new Animated.Value(0.8)).current;
  const haloOpacity = useRef(new Animated.Value(0.8)).current;
  const slideAnim = useRef(new Animated.Value(30)).current;
  const opacityAnim = useRef(new Animated.Value(0)).current;

  const formattedOrderId = orderId
    ? String(orderId).startsWith("#")
      ? orderId
      : `#${orderId}`
    : "";

  // Clean navigation helper: resets CartStack so CartScreen is always root, then navigates to target
  const handleCleanExit = (targetAction: () => void) => {
    if (isNavigatingRef.current) return;
    isNavigatingRef.current = true;

    // Reset CartStack back to CartScreen so CartTab never gets stuck showing OrderSuccess
    try {
      navigation.reset({
        index: 0,
        routes: [{ name: "CartScreen" }],
      });
    } catch (e) {
      console.log("CartStack reset fallback:", e);
    }

    targetAction();
  };

  const handleGoHome = () => {
    triggerHaptic("selection");
    handleCleanExit(() => {
      navigation.getParent()?.navigate("HomeTab");
    });
  };

  const handleTrackOrder = () => {
    triggerHaptic("selection");
    handleCleanExit(() => {
      if (orderId) {
        navigation.getParent()?.navigate("OrdersTab", {
          screen: "OrderTrackingScreen",
          params: { orderId },
        });
      } else {
        navigation.getParent()?.navigate("OrdersTab", {
          screen: "OrderHistoryScreen",
        });
      }
    });
  };

  // Trigger celebration animation and sound/haptics on mount
  useEffect(() => {
    triggerHaptic("success");

    // 1. Icon Pop Spring
    Animated.spring(scaleAnim, {
      toValue: 1,
      tension: 60,
      friction: 6,
      useNativeDriver: USE_NATIVE_DRIVER,
    }).start();

    // 2. Halo Pulse Looping
    Animated.loop(
      Animated.parallel([
        Animated.timing(haloAnim, {
          toValue: 1.5,
          duration: 1800,
          easing: Easing.out(Easing.ease),
          useNativeDriver: USE_NATIVE_DRIVER,
        }),
        Animated.timing(haloOpacity, {
          toValue: 0,
          duration: 1800,
          useNativeDriver: USE_NATIVE_DRIVER,
        }),
      ]),
    ).start();

    // 3. Text Slide & Fade In
    Animated.parallel([
      Animated.timing(opacityAnim, {
        toValue: 1,
        duration: 800,
        delay: 300,
        useNativeDriver: USE_NATIVE_DRIVER,
      }),
      Animated.spring(slideAnim, {
        toValue: 0,
        tension: 40,
        friction: 8,
        delay: 300,
        useNativeDriver: USE_NATIVE_DRIVER,
      }),
    ]).start();

    // 4. Auto-redirect to order page after 4 seconds
    const timer = setTimeout(() => {
      handleTrackOrder();
    }, 4000);

    return () => clearTimeout(timer);
  }, []);

  // Hardware Back Button intercepts and redirects cleanly to Home
  useEffect(() => {
    const onBackPress = () => {
      handleGoHome();
      return true;
    };
    const subscription = BackHandler.addEventListener(
      "hardwareBackPress",
      onBackPress,
    );
    return () => subscription.remove();
  }, []);

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: colors.background }]}
    >
      <View style={styles.content}>
        {/* Animated Celebration Badge */}
        <View style={styles.haloWrapper}>
          {/* Pulsing Radiance Ring */}
          <Animated.View
            style={[
              styles.haloRing,
              {
                transform: [{ scale: haloAnim }],
                opacity: haloOpacity,
              },
            ]}
          />

          {/* Spring Checkmark Circle */}
          <Animated.View
            style={[
              styles.iconContainer,
              { transform: [{ scale: scaleAnim }] },
            ]}
          >
            <Feather name="check" size={50} color="#FFFFFF" />
          </Animated.View>

          {/* Floating celebratory particles */}
          <View style={styles.floatingEmojiLeft}>
            <Text style={{ fontSize: 24 }}>🎉</Text>
          </View>
          <View style={styles.floatingEmojiRight}>
            <Text style={{ fontSize: 22 }}>🛍️</Text>
          </View>
          <View style={styles.floatingEmojiBottom}>
            <Text style={{ fontSize: 20 }}>✨</Text>
          </View>
        </View>

        {/* Animated Headline & Subtitle */}
        <Animated.View
          style={[
            styles.textWrapper,
            { opacity: opacityAnim, transform: [{ translateY: slideAnim }] },
          ]}
        >
          <Text style={[styles.title, { color: colors.text }]}>
            Order Confirmed!
          </Text>
          <Text style={[styles.subtitle, { color: colors.textSecondary }]}>
            Your grocery order{" "}
            <Text style={[styles.orderIdBold, { color: colors.text }]}>
              {formattedOrderId}
            </Text>{" "}
            has been received and is being packed fresh with care!
          </Text>

          {/* Action Buttons */}
          <TouchableOpacity
            style={[styles.primaryButton, { backgroundColor: colors.primary }]}
            onPress={handleTrackOrder}
            activeOpacity={0.88}
          >
            <Feather name="package" size={18} color="#FFFFFF" />
            <Text style={styles.primaryButtonText}>Track Order Live</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[
              styles.secondaryButton,
              { backgroundColor: colors.surface, borderColor: colors.border },
            ]}
            onPress={handleGoHome}
            activeOpacity={0.88}
          >
            <Feather name="shopping-bag" size={16} color={colors.primary} />
            <Text
              style={[styles.secondaryButtonText, { color: colors.primary }]}
            >
              Continue Shopping
            </Text>
          </TouchableOpacity>
        </Animated.View>
      </View>
    </SafeAreaView>
  );
}

