import { Feather } from "@expo/vector-icons";
import React, {
  useState,
  useEffect,
  useCallback,
  useMemo,
  useRef,
} from "react";
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  ActivityIndicator,
  TouchableOpacity,
  ScrollView,
  Dimensions,
  Alert,
  Platform,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { apiClient } from "../../api/client";
import { AnimatedFadeIn } from "../../components/AnimatedFadeIn";
import { ProductCard } from "../../components/ProductCard";
import { ProductCardSkeleton } from "../../components/SkeletonLoader";
import { useAuth } from "../../context/AuthContext";
import { useCart } from "../../context/CartContext";
import { useLanguage } from "../../context/LanguageContext";
import { useTheme } from "../../context/ThemeContext";
import { AppNavigationProp } from "../../navigation/types";
import { favoritesService } from "../../services/favoritesService";
import { triggerHaptic } from "../../utils/haptics";

const { width } = Dimensions.get("window");

type SortOption = "default" | "price_low" | "price_high" | "newest";

const SORT_OPTIONS: { id: SortOption; label: string }[] = [
  { id: "default", label: "Relevance" },
  { id: "price_low", label: "Price: Low to High" },
  { id: "price_high", label: "Price: High to Low" },
  { id: "newest", label: "Newest" },
];

type CacheEntry = {
  products: any[];
  nextUrl: string | null;
  timestamp: number;
};

// Module-level in-memory cache per section/category (TTL: 3 minutes)
const productSectionCache = new Map<string, CacheEntry>();
const CACHE_TTL_MS = 3 * 60 * 1000;

const getSectionCacheKey = (
  category: number | null,
  search: string,
  sort: SortOption,
) => {
  return `${category ?? "all"}_${search.trim().toLowerCase()}_${sort}`;
};

let cachedCategories: any[] | null = null;

export function ProductListScreen({
  navigation,
  route,
}: {
  navigation: AppNavigationProp;
  route: any;
}) {
  const initialCategoryId = route.params?.categoryId || null;
  const initialCategoryName = route.params?.categoryName || "All Products";
  const initialSearch = route.params?.search || "";

  const { user } = useAuth();
  const { cart, addToCart, cartQuantityMap } = useCart();
  const { colors, isDark } = useTheme();
  const { t } = useLanguage();

  const [categories, setCategories] = useState<any[]>(cachedCategories || []);
  const [selectedCategory, setSelectedCategory] = useState<number | null>(
    initialCategoryId,
  );
  const [searchQuery, setSearchQuery] = useState<string>(initialSearch);
  const [sortOption, setSortOption] = useState<SortOption>("default");

  useEffect(() => {
    if (route.params?.categoryId !== undefined) {
      setSelectedCategory(route.params.categoryId);
    }
    if (route.params?.search !== undefined) {
      setSearchQuery(route.params.search);
    }
  }, [route.params?.categoryId, route.params?.search]);

  const [products, setProducts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isRevalidating, setIsRevalidating] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  // Favorites state synced via favoritesService
  const [favoriteIds, setFavoriteIds] = useState<Set<number>>(
    favoritesService.getFavoriteIds(),
  );
  const [favoriteMap, setFavoriteMap] = useState<Record<number, number>>(
    favoritesService.getFavoriteMap(),
  );

  const getOrderingParam = (sort: SortOption): string | undefined => {
    switch (sort) {
      case "price_low":
        return "offer_price";
      case "price_high":
        return "-offer_price";
      case "newest":
        return "-created_at";
      case "default":
      default:
        return undefined;
    }
  };

  const fetchFavorites = useCallback(
    async (force = false) => {
      if (!user) {
        setFavoriteIds(new Set());
        setFavoriteMap({});
        return;
      }
      try {
        const snap = await favoritesService.getFavorites(force);
        setFavoriteIds(new Set(snap.ids));
        setFavoriteMap({ ...snap.map });
      } catch (err) {
        console.log("Error fetching favorites:", err);
      }
    },
    [user],
  );

  const toggleFavorite = useCallback(
    async (param: any) => {
      const productId =
        typeof param === "object" && param !== null ? param.id : Number(param);
      if (!productId) return;

      if (!user) {
        Alert.alert(
          "Sign In Required",
          "Please sign in to save your favorite products.",
          [
            { text: "Cancel", style: "cancel" },
            { text: "Sign In", onPress: () => navigation.navigate("Login") },
          ],
        );
        return;
      }

      try {
        await favoritesService.toggleFavorite(productId);
      } catch (error) {
        console.error("Error toggling favorite:", error);
      }
    },
    [user, navigation],
  );

  useEffect(() => {
    if (user) {
      fetchFavorites();
      const unsubscribe = favoritesService.subscribe(() => {
        setFavoriteIds(new Set(favoritesService.getFavoriteIds()));
        setFavoriteMap({ ...favoritesService.getFavoriteMap() });
      });
      return unsubscribe;
    } else {
      setFavoriteIds(new Set());
      setFavoriteMap({});
    }
  }, [user, fetchFavorites]);

  useEffect(() => {
    fetchCategories();
  }, []);

  useEffect(() => {
    const key = getSectionCacheKey(selectedCategory, searchQuery, sortOption);
    const cached = productSectionCache.get(key);

    if (cached) {
      // 0ms instant display from section cache! Zero skeleton flash!
      setProducts(cached.products);
      setHasMore(Boolean(cached.nextUrl));
      setPage(1);
      setLoading(false);

      // Silent background revalidation
      fetchProducts(1, true, true);
    } else {
      // First visit to this section
      fetchProducts(1, true, false);
    }
  }, [selectedCategory, searchQuery, sortOption]);

  const fetchCategories = async () => {
    if (cachedCategories && cachedCategories.length > 0) {
      setCategories(cachedCategories);
      return;
    }
    try {
      const res = await apiClient.get("/categories/");
      const cats = Array.isArray(res.data) ? res.data : res.data?.results || [];
      cachedCategories = cats;
      setCategories(cats);
    } catch (err) {
      console.error("Error fetching categories", err);
    }
  };

  const fetchProducts = async (
    pageNum: number,
    isReset = false,
    isSilent = false,
  ) => {
    if (isReset && abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    const currentAbortController = new AbortController();
    if (isReset) {
      abortControllerRef.current = currentAbortController;
    }
    const key = getSectionCacheKey(selectedCategory, searchQuery, sortOption);

    if (isReset) {
      if (!isSilent) {
        setLoading(true);
      } else {
        setIsRevalidating(true);
      }
      setPage(1);
    }

    try {
      const params: any = { page: pageNum };
      if (selectedCategory) params.category = selectedCategory;
      if (searchQuery) params.search = searchQuery;

      const ordering = getOrderingParam(sortOption);
      if (ordering) params.ordering = ordering;

      const res = await apiClient.get("/products/", {
        params,
        signal: currentAbortController.signal,
      });
      const newItems = Array.isArray(res.data)
        ? res.data
        : res.data?.results || [];
      const nextUrl = res.data?.next;

      if (isReset) {
        setProducts(newItems);
        productSectionCache.set(key, {
          products: newItems,
          nextUrl: nextUrl || null,
          timestamp: Date.now(),
        });
      } else {
        setProducts((prev) => {
          const updated = [...prev, ...newItems];
          productSectionCache.set(key, {
            products: updated,
            nextUrl: nextUrl || null,
            timestamp: Date.now(),
          });
          return updated;
        });
      }
      setHasMore(Boolean(nextUrl));
      setPage(pageNum);
    } catch (error: any) {
      if (error?.name === "CanceledError" || error?.message === "canceled") {
        return; // Request was cancelled, do not update state
      }
      console.error("Error fetching products:", error);
    } finally {
      setLoading(false);
      setRefreshing(false);
      setLoadingMore(false);
      setIsRevalidating(false);
    }
  };

  const loadMore = () => {
    if (!loading && !loadingMore && hasMore) {
      setLoadingMore(true);
      fetchProducts(page + 1, false);
    }
  };

  const sortedProducts = products;

  const activeCategoryObj = categories.find((c) => c.id === selectedCategory);
  const activeCategoryName = selectedCategory
    ? activeCategoryObj?.name || initialCategoryName
    : searchQuery
      ? `Search: "${searchQuery}"`
      : "All Products";

  const getItemLayout = useCallback(
    (_: any, index: number) => ({
      length: 310,
      offset: 310 * Math.floor(index / 2),
      index,
    }),
    [],
  );

  const listHeaderElement = useMemo(
    () => (
      <View
        style={[
          styles.scrollableHeaderContainer,
          { backgroundColor: colors.surface, borderBottomColor: colors.border },
        ]}
      >
        {/* Horizontal Category Filter Pills matching web app */}
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.categoryPillsContainer}
        >
          <TouchableOpacity
            style={[
              styles.categoryPill,
              { backgroundColor: colors.inputBg, borderColor: colors.border },
              !selectedCategory && styles.categoryPillActive,
            ]}
            onPress={() => {
              triggerHaptic("selection");
              setSelectedCategory(null);
            }}
            activeOpacity={0.8}
          >
            <Text
              style={[
                styles.categoryPillText,
                { color: colors.textSecondary },
                !selectedCategory && styles.categoryPillTextActive,
              ]}
            >
              All
            </Text>
          </TouchableOpacity>

          {categories.map((cat) => {
            const isSelected = selectedCategory === cat.id;
            return (
              <TouchableOpacity
                key={cat.id}
                style={[
                  styles.categoryPill,
                  {
                    backgroundColor: colors.inputBg,
                    borderColor: colors.border,
                  },
                  isSelected && styles.categoryPillActive,
                ]}
                onPress={() => {
                  triggerHaptic("selection");
                  setSelectedCategory(cat.id);
                }}
                activeOpacity={0.8}
              >
                <Text
                  style={[
                    styles.categoryPillText,
                    { color: colors.textSecondary },
                    isSelected && styles.categoryPillTextActive,
                  ]}
                >
                  {cat.name}
                </Text>
              </TouchableOpacity>
            );
          })}
        </ScrollView>

        {/* Category Title & Count */}
        <View style={[styles.subHeaderRow, { borderTopColor: colors.border }]}>
          <Text style={[styles.categoryTitle, { color: colors.text }]}>
            {activeCategoryName}
          </Text>
          <Text
            style={[styles.productCountText, { color: colors.textSecondary }]}
          >
            {sortedProducts.length} products
          </Text>
        </View>

        {/* Sorting Pills: Relevance, Price: Low to High, Price: High to Low, Newest */}
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.categoryPillsContainer}
        >
          {SORT_OPTIONS.map((opt) => (
            <TouchableOpacity
              key={opt.id}
              style={[
                styles.sortChip,
                { backgroundColor: colors.inputBg, borderColor: colors.border },
                sortOption === opt.id && [
                  styles.sortChipActive,
                  isDark && {
                    backgroundColor: "rgba(16, 185, 129, 0.2)",
                    borderColor: colors.primary,
                  },
                ],
              ]}
              onPress={() => {
                triggerHaptic("selection");
                setSortOption(opt.id);
              }}
              activeOpacity={0.8}
            >
              <Text
                style={[
                  styles.sortChipText,
                  { color: colors.textSecondary },
                  sortOption === opt.id && [
                    styles.sortChipTextActive,
                    isDark && { color: colors.primary },
                  ],
                ]}
              >
                {opt.label}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>
    ),
    [
      colors,
      isDark,
      selectedCategory,
      categories,
      activeCategoryName,
      sortedProducts.length,
      sortOption,
    ],
  );

  const handleProductPress = useCallback(
    (item: any) => {
      navigation.navigate("ProductDetailScreen", {
        productId: item.id,
        initialProduct: item,
      });
    },
    [navigation],
  );

  const handleAddToCart = useCallback(
    (p: any) => {
      addToCart(p.id, 1, p);
    },
    [addToCart],
  );

  const handleToggleFavorite = useCallback(
    (p: any) => {
      toggleFavorite(p?.id ?? p);
    },
    [toggleFavorite],
  );

  const renderProductItem = useCallback(
    ({ item, index }: { item: any; index: number }) => (
      <AnimatedFadeIn index={index} delay={50} duration={350}>
        <View style={styles.cardWrapper}>
          <ProductCard
            product={item}
            onPress={handleProductPress}
            onAddToCart={handleAddToCart}
            cartQty={cartQuantityMap[item.id] || 0}
            isFavorite={favoriteIds.has(item.id)}
            onToggleFavorite={handleToggleFavorite}
          />
        </View>
      </AnimatedFadeIn>
    ),
    [
      handleProductPress,
      handleAddToCart,
      cartQuantityMap,
      favoriteIds,
      handleToggleFavorite,
    ],
  );

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: colors.background }]}
      edges={["top"]}
    >
      {/* Compact Top Bar: Fixed Back Button & Category Name */}
      <View
        style={[
          styles.topBar,
          { backgroundColor: colors.surface, borderBottomColor: colors.border },
        ]}
      >
        <TouchableOpacity
          style={styles.backButton}
          hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
          onPress={() => {
            if (navigation.canGoBack()) {
              if (navigation.canGoBack()) {
                navigation.goBack();
              } else {
                navigation.navigate("Main");
              }
            } else {
              navigation.navigate("HomeTab");
            }
          }}
          activeOpacity={0.7}
        >
          <Feather name="arrow-left" size={18} color={colors.primary} />
          <Text style={[styles.backButtonText, { color: colors.primary }]}>
            {t("back")}
          </Text>
        </TouchableOpacity>

        <Text
          style={[styles.topBarTitle, { color: colors.text }]}
          numberOfLines={1}
        >
          {activeCategoryName}
        </Text>

        <View
          style={[
            styles.topBarBadge,
            isDark && { backgroundColor: colors.inputBg },
          ]}
        >
          {isRevalidating ? (
            <ActivityIndicator size="small" color={colors.primary} />
          ) : (
            <Text style={[styles.topBarBadgeText, { color: colors.primary }]}>
              {sortedProducts.length}
            </Text>
          )}
        </View>
      </View>

      {loading ? (
        <ScrollView
          contentContainerStyle={styles.listContainer}
          showsVerticalScrollIndicator={false}
        >
          {listHeaderElement}
          <View style={styles.row}>
            <View style={styles.cardWrapper}>
              <ProductCardSkeleton />
            </View>
            <View style={styles.cardWrapper}>
              <ProductCardSkeleton />
            </View>
          </View>
          <View style={styles.row}>
            <View style={styles.cardWrapper}>
              <ProductCardSkeleton />
            </View>
            <View style={styles.cardWrapper}>
              <ProductCardSkeleton />
            </View>
          </View>
          <View style={styles.row}>
            <View style={styles.cardWrapper}>
              <ProductCardSkeleton />
            </View>
            <View style={styles.cardWrapper}>
              <ProductCardSkeleton />
            </View>
          </View>
        </ScrollView>
      ) : sortedProducts.length === 0 ? (
        <ScrollView
          contentContainerStyle={styles.listContainer}
          showsVerticalScrollIndicator={false}
        >
          {listHeaderElement}
          <View style={styles.emptyContainer}>
            <View
              style={[
                styles.emptyIconCircle,
                {
                  backgroundColor: isDark
                    ? "rgba(255, 255, 255, 0.08)"
                    : "#F1F5F9",
                },
              ]}
            >
              <Feather name="package" size={40} color={colors.textSecondary} />
            </View>
            <Text style={[styles.emptyTitle, { color: colors.text }]}>
              {t("noProductsFound")}
            </Text>
            <Text
              style={[styles.emptySubtitle, { color: colors.textSecondary }]}
            >
              {selectedCategory !== null || !!searchQuery
                ? "No products match your selected filters. Tap below to see all items."
                : "There are no products available in this category right now."}
            </Text>
            <TouchableOpacity
              style={styles.clearFiltersBtn}
              onPress={() => {
                triggerHaptic("selection");
                setSelectedCategory(null);
                setSearchQuery("");
                setSortOption("default");
              }}
              activeOpacity={0.8}
            >
              <Feather
                name="refresh-cw"
                size={14}
                color="#FFFFFF"
                style={{ marginRight: 6 }}
              />
              <Text style={styles.clearFiltersBtnText}>
                {t("clearFilters")}
              </Text>
            </TouchableOpacity>
          </View>
        </ScrollView>
      ) : (
        <FlatList
          data={sortedProducts}
          keyExtractor={(item, index) =>
            String(item?.id || item?.uuid || item?.uid || index)
          }
          numColumns={2}
          ListHeaderComponent={listHeaderElement}
          getItemLayout={getItemLayout}
          contentContainerStyle={styles.listContainer}
          columnWrapperStyle={styles.row}
          refreshing={refreshing}
          onRefresh={() => {
            setRefreshing(true);
            const key = getSectionCacheKey(
              selectedCategory,
              searchQuery,
              sortOption,
            );
            productSectionCache.delete(key);
            fetchProducts(1, true, false);
            fetchFavorites(true);
          }}
          renderItem={renderProductItem}
          initialNumToRender={6}
          maxToRenderPerBatch={10}
          windowSize={5}
          removeClippedSubviews={Platform.OS === "android"}
          updateCellsBatchingPeriod={50}
          onEndReached={loadMore}
          onEndReachedThreshold={0.5}
          ListFooterComponent={() =>
            loadingMore ? (
              <ActivityIndicator style={{ margin: 20 }} color="#059669" />
            ) : null
          }
        />
      )}
    </SafeAreaView>
  );
}

