import { Feather } from "@expo/vector-icons";
import React, { useState } from "react";
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  TextInput,
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Platform,
  Switch,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { apiClient } from "../../api/client";
import { useAuth } from "../../context/AuthContext";
import { useTheme } from "../../context/ThemeContext";
import { useLocation } from "../../hooks/useLocation";
import { AppNavigationProp } from "../../navigation/types";

export function AddAddressScreen({
  navigation,
  route,
}: {
  navigation: AppNavigationProp;
  route: any;
}) {
  const { colors, isDark } = useTheme();
  const { user } = useAuth();
  const editingAddress = route.params?.editingAddress;
  const {
    requestLocation,
    location: gpsLocation,
    isRequesting: gpsLoading,
  } = useLocation();

  const [title, setTitle] = useState(
    editingAddress?.title || editingAddress?.address_type || "Home",
  );
  const [street, setStreet] = useState(
    editingAddress?.street || editingAddress?.address_line_1 || "",
  );
  const [landmark, setLandmark] = useState(
    editingAddress?.landmark || editingAddress?.address_line_2 || "",
  );
  const [city, setCity] = useState(editingAddress?.city || "");
  const [district, setDistrict] = useState(editingAddress?.district || "");
  const [state, setState] = useState(editingAddress?.state || "");
  const [country, setCountry] = useState(editingAddress?.country || "India");
  const [zipCode, setZipCode] = useState(
    editingAddress?.zip_code || editingAddress?.pincode || "",
  );
  const [isDefault, setIsDefault] = useState(
    Boolean(editingAddress?.is_default),
  );
  const [latitude, setLatitude] = useState<number | null>(
    editingAddress?.latitude || null,
  );
  const [longitude, setLongitude] = useState<number | null>(
    editingAddress?.longitude || null,
  );

  const [saving, setSaving] = useState(false);

  const handleCaptureGps = async () => {
    const loc = await requestLocation();
    if (loc) {
      setLatitude(parseFloat(loc.latitude.toFixed(6)));
      setLongitude(parseFloat(loc.longitude.toFixed(6)));
      Alert.alert(
        "GPS Secured",
        "Exact location coordinates captured successfully!",
      );
    } else {
      Alert.alert(
        "Location Required",
        "Could not get GPS location. Please enable GPS permissions.",
      );
    }
  };

  const handleSave = async () => {
    if (!user) {
      Alert.alert("Sign In Required", "Please sign in to save addresses.", [
        { text: "Cancel", style: "cancel" },
        { text: "Sign In", onPress: () => navigation.navigate("Login") },
      ]);
      return;
    }

    if (
      !title.trim() ||
      !street.trim() ||
      !city.trim() ||
      !state.trim() ||
      !zipCode.trim()
    ) {
      Alert.alert(
        "Validation Error",
        "Please fill in all required fields (Label, Street, City, State, Pincode).",
      );
      return;
    }

    const cleanZip = zipCode.trim().replace(/[^0-9]/g, "");
    const pincodeRegex = /^[1-9][0-9]{5}$/;
    if (!pincodeRegex.test(cleanZip)) {
      Alert.alert(
        "Invalid Pincode",
        "Please enter a valid 6-digit Indian postal PIN code (e.g. 500001).",
      );
      return;
    }

    setSaving(true);
    const payload = {
      title,
      street,
      landmark,
      city,
      district,
      state,
      country,
      zip_code: cleanZip,
      is_default: isDefault,
      latitude,
      longitude,
    };

    try {
      if (editingAddress?.id) {
        await apiClient.put(`/auth/addresses/${editingAddress.id}/`, payload);
        Alert.alert("Success", "Address updated successfully!");
      } else {
        await apiClient.post("/auth/addresses/", payload);
        Alert.alert("Success", "Address saved successfully!");
      }
      if (navigation.canGoBack()) {
        navigation.goBack();
      } else {
        navigation.navigate("Main");
      }
    } catch (err: any) {
      const msg =
        err.response?.data?.latitude?.[0] ||
        err.response?.data?.detail ||
        err.response?.data?.error ||
        "Failed to save address.";
      Alert.alert("Error", msg);
    } finally {
      setSaving(false);
    }
  };

  if (!user) {
    return (
      <SafeAreaView
        style={[styles.container, { backgroundColor: colors.background }]}
        edges={["top"]}
      >
        <View
          style={[
            styles.header,
            {
              backgroundColor: colors.surface,
              borderBottomColor: colors.border,
            },
          ]}
        >
          <TouchableOpacity
            style={styles.backButton}
            hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            onPress={() =>
              navigation.canGoBack()
                ? navigation.goBack()
                : navigation.navigate("Main")
            }
          >
            <Feather name="arrow-left" size={18} color={colors.primary} />
            <Text style={[styles.backButtonText, { color: colors.primary }]}>
              Back
            </Text>
