import { Feather } from "@expo/vector-icons";
import React, { useState, useEffect, useCallback } from "react";
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  ActivityIndicator,
  TouchableOpacity,
  Alert,
  RefreshControl,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { apiClient } from "../../api/client";
import { useAuth } from "../../context/AuthContext";
import { useTheme } from "../../context/ThemeContext";
import { AppNavigationProp } from "../../navigation/types";
import {
  getCachedAddressesSync,
  loadCachedAddresses,
  saveCachedAddresses,
} from "../../services/profileCache";

export function AddressesScreen({
  navigation,
}: {
  navigation: AppNavigationProp;
}) {
  const { colors, isDark } = useTheme();
  const { user } = useAuth();
  const cachedAddresses = getCachedAddressesSync(user?.id);
  const [addresses, setAddresses] = useState<any[]>(cachedAddresses || []);
  const [loading, setLoading] = useState(
    !cachedAddresses || cachedAddresses.length === 0,
  );
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    if (!user) {
      setAddresses([]);
      setLoading(false);
      return;
    }
    if (addresses.length === 0) {
      loadCachedAddresses(user.id).then((cached) => {
        if (cached && cached.length > 0) {
          setAddresses(cached);
          setLoading(false);
        }
      });
    }
    const unsubscribe = navigation.addListener("focus", () => {
      fetchAddresses();
    });
    fetchAddresses();
    return unsubscribe;
  }, [navigation, user]);

  const fetchAddresses = async () => {
    if (!user) {
      setLoading(false);
      setRefreshing(false);
      return;
    }
    try {
      const res = await apiClient.get("/auth/addresses/");
      const list = Array.isArray(res.data) ? res.data : res.data?.results || [];
      setAddresses(list);
      saveCachedAddresses(user.id, list);
    } catch (error) {
      console.error("Error fetching addresses:", error);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const onRefresh = useCallback(() => {
    if (!user) {
      setRefreshing(false);
      return;
    }
    setRefreshing(true);
    fetchAddresses();
  }, [user]);

  const deleteAddress = async (id: number) => {
    Alert.alert(
      "Delete Address",
      "Are you sure you want to remove this delivery address?",
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Delete",
          style: "destructive",
          onPress: async () => {
            try {
              await apiClient.delete(`/auth/addresses/${id}/`);
              setAddresses((prev) => prev.filter((a) => a.id !== id));
            } catch (err) {
              Alert.alert("Error", "Failed to delete address.");
            }
          },
        },
      ],
    );
  };

  const handleSetDefault = async (id: number) => {
    try {
      await apiClient.patch(`/auth/addresses/${id}/`, { is_default: true });
      setAddresses((prev) =>
        prev.map((a) => ({
          ...a,
          is_default: a.id === id,
        })),
      );
    } catch (err) {
      console.error("Failed to set default address:", err);
      Alert.alert("Error", "Failed to set default address.");
    }
  };

  if (!user) {
    return (
      <SafeAreaView
        style={[styles.container, { backgroundColor: colors.background }]}
        edges={["top"]}
      >
        <View
          style={[
            styles.header,
            {
              backgroundColor: colors.surface,
              borderBottomColor: colors.border,
            },
          ]}
        >
          <TouchableOpacity
            style={styles.backButton}
            hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            onPress={() =>
              navigation.canGoBack()
                ? navigation.goBack()
                : navigation.navigate("Main")
            }
          >
            <Feather name="arrow-left" size={18} color={colors.primary} />
            <Text style={[styles.backButtonText, { color: colors.primary }]}>
              Back
            </Text>
          </TouchableOpacity>
          <Text style={[styles.headerTitle, { color: colors.text }]}>
            Saved Addresses
          </Text>
        </View>
        <View style={styles.guestStateContainer}>
          <View
            style={[
              styles.guestIconBox,
              {
                backgroundColor: isDark ? "rgba(5, 150, 105, 0.15)" : "#ECFDF5",
              },
            ]}
          >
            <Feather name="map-pin" size={44} color={colors.primary} />
          </View>
          <Text style={[styles.guestTitle, { color: colors.text }]}>
            Sign In to Access Addresses
          </Text>
          <Text style={[styles.guestSubtitle, { color: colors.textSecondary }]}>
            Save delivery addresses for faster checkout, live GPS tracking, and
            seamless ordering.
          </Text>
          <TouchableOpacity
            style={[styles.guestSignInBtn, { backgroundColor: colors.primary }]}
            onPress={() => navigation.navigate("Login")}
            activeOpacity={0.85}
          >
            <Feather
              name="log-in"
              size={16}
              color="#FFFFFF"
              style={{ marginRight: 8 }}
            />
            <Text style={styles.guestSignInBtnText}>Sign In / Register</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    );
  }

  if (loading && addresses.length === 0) {
    return (
      <SafeAreaView
        style={[styles.container, { backgroundColor: colors.background }]}
        edges={["top"]}
      >
        <View
          style={[
            styles.header,
            {
              backgroundColor: colors.surface,
              borderBottomColor: colors.border,
            },
          ]}
        >
          <TouchableOpacity
            style={styles.backButton}
            hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            onPress={() =>
              navigation.canGoBack()
                ? navigation.goBack()
                : navigation.navigate("Main")
            }
          >
            <Feather name="arrow-left" size={18} color={colors.primary} />
            <Text style={[styles.backButtonText, { color: colors.primary }]}>
              Back
            </Text>
          </TouchableOpacity>
          <Text style={[styles.headerTitle, { color: colors.text }]}>
            Saved Addresses
          </Text>
        </View>
        <View style={styles.center}>
          <ActivityIndicator size="large" color={colors.primary} />
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: colors.background }]}
      edges={["top"]}
    >
      {/* Header matching web SavedAddresses.jsx */}
      <View
        style={[
          styles.header,
          { backgroundColor: colors.surface, borderBottomColor: colors.border },
        ]}
      >
        <TouchableOpacity
          style={styles.backButton}
          hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
          onPress={() =>
            navigation.canGoBack()
              ? navigation.goBack()
              : navigation.navigate("Main")
          }
          activeOpacity={0.7}
        >
          <Feather name="arrow-left" size={18} color={colors.primary} />
          <Text style={[styles.backButtonText, { color: colors.primary }]}>
            Back
          </Text>
        </TouchableOpacity>

