import { Feather, Ionicons, MaterialIcons } from "@expo/vector-icons";
import * as Clipboard from "expo-clipboard";
import { Image } from "expo-image";
import { LinearGradient } from "expo-linear-gradient";
import React, { useState, useEffect } from "react";
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  ActivityIndicator,
  Alert,
  Share,
  Modal,
  useWindowDimensions,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { apiClient } from "../../api/client";
import { useAuth } from "../../context/AuthContext";
import { useTheme } from "../../context/ThemeContext";
import { AppNavigationProp } from "../../navigation/types";
import {
  getCachedReferralsSync,
  loadCachedReferrals,
  saveCachedReferrals,
} from "../../services/profileCache";

export function ReferAndEarnScreen({
  navigation,
}: {
  navigation: AppNavigationProp;
}) {
  const { colors, isDark } = useTheme();
  const { user } = useAuth();

  const cachedData = getCachedReferralsSync(user?.id);
  const [settings, setSettings] = useState<any>(cachedData?.settings || null);
  const [history, setHistory] = useState<any[]>(cachedData?.history || []);
  const [wallet, setWallet] = useState<any>(cachedData?.wallet || null);
  const [milestones, setMilestones] = useState<any[]>(
    cachedData?.milestones || [],
  );
  const [loading, setLoading] = useState(!cachedData);
  const [copied, setCopied] = useState(false);
  const [activeTab, setActiveTab] = useState<"network" | "rewards">("network");

  const [qrModal, setQrModal] = useState<{
    isOpen: boolean;
    referralId: any;
    base64: string | null;
  }>({
    isOpen: false,
    referralId: null,
    base64: null,
  });
  const [loadingQrFor, setLoadingQrFor] = useState<number | null>(null);

  useEffect(() => {
    if (user) {
      if (!settings) {
        loadCachedReferrals(user.id).then((cached) => {
          if (cached) {
            if (cached.settings) setSettings(cached.settings);
            if (cached.history) setHistory(cached.history);
            if (cached.wallet) setWallet(cached.wallet);
            if (cached.milestones) setMilestones(cached.milestones);
            setLoading(false);
          }
        });
      }
      fetchData();
    } else {
      setLoading(false);
    }
  }, [user]);

  // Automatically poll for status change while QR is open
  useEffect(() => {
    let intervalId: any;
    if (user && qrModal.isOpen && qrModal.referralId) {
      intervalId = setInterval(async () => {
        try {
          const res = await apiClient.get("/offers/referrals/");
          const latestHistory = Array.isArray(res.data)
            ? res.data
            : res.data?.results || [];
          const currentRef = latestHistory.find(
            (h: any) => h.id === qrModal.referralId,
          );

          if (currentRef && currentRef.status === "COMPLETED") {
            setHistory(latestHistory);
            setQrModal({ isOpen: false, referralId: null, base64: null });
            Alert.alert(
              "Reward Approved! 🎉",
              "Your referral reward has been approved by the store owner!",
            );
          }
        } catch (e) {
          console.error("Polling error", e);
        }
      }, 3000);
    }
    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [user, qrModal.isOpen, qrModal.referralId]);

  const fetchData = async () => {
    if (!user) {
      setLoading(false);
      return;
    }
    try {
      const [settingsRes, historyRes, walletRes, milestonesRes] =
        await Promise.all([
          apiClient
            .get("/offers/referral-settings/")
            .catch(() => ({ data: {} })),
          apiClient.get("/offers/referrals/").catch(() => ({ data: [] })),
          apiClient
            .get("/auth/wallet/")
            .catch(() => ({ data: { balance: 0, transactions: [] } })),
          apiClient
            .get("/offers/referral-milestones/")
            .catch(() => ({ data: [] })),
        ]);

      const newSettings = settingsRes.data || {};
      const newHistory = Array.isArray(historyRes.data)
        ? historyRes.data
        : historyRes.data?.results || [];
      const newWallet = walletRes.data || {};
      const newMilestones = Array.isArray(milestonesRes.data)
        ? milestonesRes.data
        : milestonesRes.data?.results || [];

      setSettings(newSettings);
      setHistory(newHistory);
      setWallet(newWallet);
      setMilestones(newMilestones);

      saveCachedReferrals(user.id, {
        settings: newSettings,
        history: newHistory,
        wallet: newWallet,
        milestones: newMilestones,
      });
    } catch (err) {
      console.error("Error loading referral data", err);
    } finally {
      setLoading(false);
    }
  };

  const { width: screenWidth } = useWindowDimensions();
  const isCompact = screenWidth < 375 || milestones.length > 3;

  const referralCode =
    user?.customer_profile?.referral_code ||
    user?.referral_code ||
    `REF-${(user?.username || "USER").slice(0, 5).toUpperCase()}`;

  const handleCopy = async () => {
    await Clipboard.setStringAsync(referralCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    const storeLink = "https://narendra-kirana.vercel.app";
    let shareText = "";
    if (settings?.share_text_template) {
      if (settings.share_text_template.includes("{link}")) {
        shareText = settings.share_text_template
          .replace("{code}", referralCode)
          .replace("{link}", storeLink);
      } else {
        shareText = `${settings.share_text_template.replace("{code}", referralCode).trim()}\n${storeLink}`;
      }
    } else {
      shareText = `Shop online at Narendra Kirana and get special discounts! Use my referral code: ${referralCode}\n${storeLink}`;
    }
    shareText = shareText
      .replace(/[ \t]+/g, " ")
      .replace(/\n\s+/g, "\n")
      .trim();

    try {
      await Share.share({
        message: shareText,
        title: "Join me on Narendra Kirana",
      });
    } catch (error: any) {
      console.error(error);
    }
  };

  const handleShowQR = async (referralId: number) => {
    try {
      setLoadingQrFor(referralId);
      const res = await apiClient.get(
        `/offers/referrals/${referralId}/qr_code/`,
      );
      setQrModal({
        isOpen: true,
        referralId,
        base64: res.data?.qr_code_base64 || null,
      });
    } catch (err: any) {
      Alert.alert(
        "Error",
        err.response?.data?.detail || "Failed to load QR code.",
      );
    } finally {
      setLoadingQrFor(null);
    }
  };

  const handleClaim = async (referralId: number) => {
    try {
      await apiClient.post(`/offers/referrals/${referralId}/claim/`);
      Alert.alert(
        "Reward Claimed",
        "Show this QR code to the store owner at checkout.",
      );
      setHistory((prev) =>
        prev.map((h) =>
          h.id === referralId ? { ...h, status: "AWAITING_APPROVAL" } : h,
        ),
      );
      handleShowQR(referralId);
    } catch (err) {
      Alert.alert("Error", "Failed to claim reward.");
    }
  };

  const completedReferrals = history.filter(
    (h) => h.status === "COMPLETED",
  ).length;
  const pendingReferrals = history.filter((h) => h.status === "PENDING").length;
  const readyToClaim = history.filter(
    (h) => h.status === "READY_TO_CLAIM",
  ).length;
  const awaitingApproval = history.filter(
    (h) => h.status === "AWAITING_APPROVAL",
  ).length;

  const referralCashTransactions = (wallet?.transactions || []).filter(
    (t: any) => t.transaction_type === "REFERRAL_REWARD",
  );

  const totalCashEarned = (wallet?.transactions || [])
    .filter(
      (t: any) =>
        t.transaction_type === "REFERRAL_REWARD" ||
        t.transaction_type === "MILESTONE_BONUS",
    )
    .reduce((sum: number, t: any) => sum + parseFloat(t.amount || "0"), 0);

  const productsEarned = Math.max(
    0,
    completedReferrals - referralCashTransactions.length,
  );

  const isProductReward = Boolean(settings?.referrer_reward_product);
  const rewardText = isProductReward
    ? `a Free ${settings?.referrer_reward_product_name || "Gift"}`
    : `₹${parseFloat(settings?.referrer_reward || "50").toFixed(0)}`;

  // Milestone gamification calculations
  const sortedMilestones = [...milestones].sort(
    (a, b) => a.required_referrals - b.required_referrals,
  );
  const maxMilestoneTarget =
    sortedMilestones.length > 0
      ? sortedMilestones[sortedMilestones.length - 1].required_referrals
      : 1;
  const nextMilestone = sortedMilestones.find(
    (m) => m.required_referrals > completedReferrals,
  );
  const progressPercentage = Math.min(
    100,
    Math.max(0, (completedReferrals / maxMilestoneTarget) * 100),
  );

  if (!user) {
    return (
      <SafeAreaView
        style={[styles.container, { backgroundColor: colors.background }]}
        edges={["top"]}
      >
        <View
          style={[
            styles.header,
            {
              backgroundColor: colors.surface,
              borderBottomColor: colors.border,
            },
          ]}
        >
          <TouchableOpacity
            style={styles.backButton}
            hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            onPress={() =>
              navigation.canGoBack()
                ? navigation.goBack()
                : navigation.navigate("Main")
            }
          >
            <Feather name="arrow-left" size={18} color={colors.primary} />
            <Text style={[styles.backButtonText, { color: colors.primary }]}>
              Back
            </Text>
          </TouchableOpacity>
          <Text style={[styles.headerTitle, { color: colors.text }]}>
            Refer & Earn
          </Text>
        </View>
        <View style={styles.guestStateContainer}>
          <View
            style={[
              styles.guestIconBox,
              {
                backgroundColor: isDark ? "rgba(5, 150, 105, 0.15)" : "#ECFDF5",
              },
            ]}
          >
            <Feather name="gift" size={44} color={colors.primary} />
          </View>
          <Text style={[styles.guestTitle, { color: colors.text }]}>
            Sign In to Access Refer & Earn
          </Text>
          <Text style={[styles.guestSubtitle, { color: colors.textSecondary }]}>
            Invite your friends and family to shop at Narendra Kirana and earn
            exclusive discounts, cash rewards, and free items.
          </Text>
          <TouchableOpacity
            style={[styles.guestSignInBtn, { backgroundColor: colors.primary }]}
            onPress={() => navigation.navigate("Login")}
            activeOpacity={0.85}
          >
            <Feather
              name="log-in"
              size={16}
              color="#FFFFFF"
              style={{ marginRight: 8 }}
            />
            <Text style={styles.guestSignInBtnText}>Sign In / Register</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    );
  }

  if (loading && !settings) {
    return (
      <SafeAreaView
        style={[styles.container, { backgroundColor: colors.background }]}
        edges={["top"]}
      >
        <View
          style={[
            styles.header,
            {
              backgroundColor: colors.surface,
              borderBottomColor: colors.border,
            },
          ]}
        >
          <TouchableOpacity
            style={styles.backButton}
            hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            onPress={() =>
              navigation.canGoBack()
                ? navigation.goBack()
                : navigation.navigate("Main")
            }
