                setQrModal({ isOpen: false, referralId: null, base64: null })
              }
            >
              <Text style={styles.closeModalBtnText}>Close Pass</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

