import { isRunningInExpoGo } from "expo";
import Constants, { ExecutionEnvironment } from "expo-constants";
import * as Device from "expo-device";
import { Platform } from "react-native";

import { apiClient } from "../api/client";
import { getItem, saveItem, deleteItem } from "../utils/storage";

const PUSH_TOKEN_KEY = "user_device_push_token";

/**
 * Detect if currently running inside the Expo Go app client.
 * Expo SDK 53+ removed remote FCM push notification token support from Expo Go on Android.
 */
export const isExpoGo =
  isRunningInExpoGo() ||
  Constants?.appOwnership === "expo" ||
  Constants?.executionEnvironment === ExecutionEnvironment.StoreClient;

export const isExpoGoAndroid = isExpoGo && Platform.OS === "android";

// Lazy-load expo-notifications only when NOT running in Expo Go on Android.
// Statically importing expo-notifications executes DevicePushTokenAutoRegistration.fx at startup,
// which invokes warnOfExpoGoPushUsage and throws an uncatchable runtime error in Expo Go SDK 53+ on Android.
type NotificationsModuleType = any;
let NotificationsModule: NotificationsModuleType | null = null;
let hasAttemptedLoad = false;

export function getNotifications(): NotificationsModuleType | null {
  if (isExpoGoAndroid || Platform.OS === "web") {
    return null;
  }
  if (!hasAttemptedLoad) {
    hasAttemptedLoad = true;
    try {
      const mod = require("expo-notifications");
      mod?.setNotificationHandler?.({
        handleNotification: async () => ({
          shouldShowAlert: true,
          shouldPlaySound: true,
          shouldSetBadge: true,
          shouldShowBanner: true,
          shouldShowList: true,
        }),
      });
      NotificationsModule = mod;
    } catch (err) {
      if (__DEV__) {
        console.log(
          "[NotificationService] expo-notifications not available in this environment",
        );
      }
      NotificationsModule = null;
    }
  }
  return NotificationsModule;
}

/**
 * Configure high-priority Android notification channels for order updates
 */
export async function setupNotificationChannels(): Promise<void> {
  const Notifications = getNotifications();
  if (Platform.OS === "android" && Notifications) {
    try {
      await Notifications.setNotificationChannelAsync("orders", {
        name: "Order Updates & Delivery",
        importance: Notifications.AndroidImportance.MAX,
        vibrationPattern: [0, 250, 250, 250],
        lightColor: "#10B981",
        sound: "default",
        enableVibrate: true,
        showBadge: true,
        lockscreenVisibility:
          Notifications.AndroidNotificationVisibility.PUBLIC,
        bypassDnd: false,
      });

      await Notifications.setNotificationChannelAsync("general", {
        name: "Offers & Announcements",
        importance: Notifications.AndroidImportance.DEFAULT,
        sound: "default",
      });
    } catch (error) {
      console.log(
        "[NotificationService] Notice: Android notification channels skipped:",
        error,
      );
    }
  }
}

/**
 * Configure interactive action buttons for notifications in notification drawer
 */
export async function setupNotificationCategories(): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) return;

  try {
    // Delivery in progress category
    await Notifications.setNotificationCategoryAsync("ORDER_DELIVERY", [
      {
        identifier: "TRACK_ORDER",
        buttonTitle: "🗺️ Track Live",
        options: { opensAppToForeground: true },
      },
      {
        identifier: "VIEW_ORDER",
        buttonTitle: "📦 View Order",
        options: { opensAppToForeground: true },
      },
    ]);

    // Rider arriving category (with OTP quick action)
    await Notifications.setNotificationCategoryAsync("RIDER_ARRIVING", [
      {
        identifier: "VIEW_OTP",
        buttonTitle: "🔑 View OTP",
        options: { opensAppToForeground: true },
      },
      {
        identifier: "TRACK_ORDER",
        buttonTitle: "🗺️ Live Map",
        options: { opensAppToForeground: true },
      },
    ]);

    // Order ready category
    await Notifications.setNotificationCategoryAsync("ORDER_READY", [
      {
        identifier: "VIEW_ORDER",
        buttonTitle: "🛍️ Pickup Info",
        options: { opensAppToForeground: true },
      },
    ]);
  } catch (error) {
    console.log(
      "[NotificationService] Notification categories skipped:",
      error,
    );
  }
}

/**
 * Display a heads-up banner directly in the mobile device's top system notification bar with sound and action buttons
 */
export async function showSystemNotification({
  title,
  body,
  data = {},
  categoryId = "ORDER_DELIVERY",
  channelId = "orders",
}: {
  title: string;
  body: string;
  data?: Record<string, any>;
  categoryId?: string;
  channelId?: string;
}): Promise<void> {
  const Notifications = getNotifications();
  if (!Notifications) return;

  try {
    await setupNotificationChannels();
    await setupNotificationCategories();

    await Notifications.scheduleNotificationAsync({
      content: {
        title,
        body,
        data,
        categoryIdentifier: categoryId,
        sound: "default",
        channelId,
      },
      trigger: null, // Display immediately in system bar
    });
  } catch (err) {
    console.warn("[NotificationService] showSystemNotification failed:", err);
  }
}

/**
 * Requests push permissions and registers the Expo push token with the Django backend.
 * In Expo Go on Android (Expo SDK 53+), remote push notifications are not supported
 * by the prebuilt Expo Go client. In that case, this function gracefully logs a notice
 * and returns null without throwing, preserving full functionality for development and production builds.
 */
export async function registerForPushNotificationsAsync(): Promise<
  string | null
> {
  // In Expo Go on Android, remote push notification tokens are restricted by Expo SDK 53+
  if (isExpoGoAndroid) {
    console.log(
      "[NotificationService] Notice: Remote push tokens are disabled in Expo Go on Android (Expo SDK 53+ requirement). Skipping remote token registration; local notifications and in-app updates remain fully active. For remote push on physical device, use a development build (expo-dev-client) or standalone APK.",
    );
    return null;
  }

  const Notifications = getNotifications();
  if (!Notifications) {
    return null;
  }

  let token: string | null = null;

  try {
    // Setup Android channels and interactive action categories first
    await setupNotificationChannels();
    await setupNotificationCategories();

    // Check if running on a physical device (push tokens require physical device)
    if (!Device.isDevice) {
      console.log(
        "[NotificationService] Running in emulator/simulator. Remote push tokens unavailable.",
      );
      return null;
    }

    const { status: existingStatus } =
      await Notifications.getPermissionsAsync();
    let finalStatus = existingStatus;

    if (existingStatus !== "granted") {
      const { status } = await Notifications.requestPermissionsAsync();
      finalStatus = status;
    }

    if (finalStatus !== "granted") {
      console.log(
        "[NotificationService] Push notification permission not granted by user.",
      );
      return null;
    }

    // Safely retrieve Expo push token
    try {
      const projectId =
        Constants?.expoConfig?.extra?.eas?.projectId ??
        Constants?.easConfig?.projectId;

      const pushTokenData = projectId
        ? await Notifications.getExpoPushTokenAsync({ projectId })
        : await Notifications.getExpoPushTokenAsync();

      token = pushTokenData?.data || null;
    } catch (tokenErr: any) {
      console.log(
        "[NotificationService] Could not obtain push token (safe fallback for Expo Go without EAS credentials):",
        tokenErr?.message || tokenErr,
      );
      return null;
    }

    if (token) {
      // Check if already registered to avoid redundant backend requests
      const lastToken = await getItem(PUSH_TOKEN_KEY);
      if (lastToken !== token) {
        // Register token with Django backend
        await apiClient.post("/notifications/push-token/", {
          token,
          platform: Platform.OS,
          device_name:
            Device.modelName ||
            (Platform.OS === "android" ? "Android Device" : "iOS Device"),
        });
        await saveItem(PUSH_TOKEN_KEY, token);
        console.log(
          "[NotificationService] Push token registered successfully with backend:",
          token,
        );
      }
    }
  } catch (error) {
    console.warn("[NotificationService] Failed to register push token:", error);
  }

  return token;
}

/**
 * Unregisters the push token with backend on logout
 */
export async function unregisterPushNotificationsAsync(): Promise<void> {
  try {
    const token = await getItem(PUSH_TOKEN_KEY);
    if (token) {
      await apiClient
        .post("/notifications/push-token/delete/", { token })
        .catch(() => {});
      await deleteItem(PUSH_TOKEN_KEY);
      console.log("[NotificationService] Push token unregistered.");
    }
  } catch (error) {
    console.warn(
      "[NotificationService] Failed to unregister push token:",
      error,
    );
  }
}

/**
 * Attach notification received listener (fires when notification arrives while app is foregrounded)
 */
export function addNotificationReceivedListener(
  callback: (notification: any) => void,
): { remove: () => void } {
  const Notifications = getNotifications();
  if (!Notifications) {
    return { remove: () => {} };
  }
  try {
    return Notifications.addNotificationReceivedListener(callback);
  } catch (err) {
    console.log(
      "[NotificationService] Notice: addNotificationReceivedListener skipped:",
      err,
    );
    return { remove: () => {} };
  }
}

/**
 * Attach notification response listener (fires when user taps on lock-screen notification banner)
 */
export function addNotificationResponseReceivedListener(
  callback: (response: any) => void,
): { remove: () => void } {
  const Notifications = getNotifications();
  if (!Notifications) {
    return { remove: () => {} };
  }
  try {
    return Notifications.addNotificationResponseReceivedListener(callback);
  } catch (err) {
    console.log(
      "[NotificationService] Notice: addNotificationResponseReceivedListener skipped:",
      err,
    );
    return { remove: () => {} };
  }
}

/**
 * Retrieve notification response on cold start (when app is launched from a tapped notification while closed/killed)
 */
export async function getLastNotificationResponseAsync(): Promise<any | null> {
  const Notifications = getNotifications();
  if (!Notifications || !Notifications.getLastNotificationResponseAsync) {
    return null;
  }
  try {
    return await Notifications.getLastNotificationResponseAsync();
  } catch (err) {
    return null;
  }
}

import * as Haptics from "expo-haptics";
import { Platform } from "react-native";

import { getItem, saveItem } from "./storage";

export const STORAGE_VIBRATION_KEY = "sk_vibration_enabled";

let isVibrationActive = true;

// Initialize vibration preference from persistent storage safely
getItem(STORAGE_VIBRATION_KEY)
  .then((val) => {
    if (val !== null) {
      isVibrationActive = val !== "false";
    }
  })
  .catch(() => {});

export const getVibrationEnabled = (): boolean => isVibrationActive;

export const setVibrationEnabled = async (enabled: boolean): Promise<void> => {
  isVibrationActive = enabled;
  await saveItem(STORAGE_VIBRATION_KEY, enabled ? "true" : "false").catch(
    () => {},
  );
  if (enabled) {
    triggerHaptic("medium");
  }
};

export const triggerHaptic = (
  type:
    | "light"
    | "medium"
    | "heavy"
    | "selection"
    | "success"
    | "warning"
    | "error" = "light",
) => {
  if (Platform.OS === "web" || !isVibrationActive) return;

  try {
    let p: Promise<void> | undefined;
    switch (type) {
      case "light":
        p = Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        break;
      case "medium":
        p = Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
        break;
      case "heavy":
        p = Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
        break;
      case "selection":
        p = Haptics.selectionAsync();
        break;
      case "success":
        p = Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
        break;
      case "warning":
        p = Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
        break;
      case "error":
        p = Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error);
        break;
    }
    p?.catch(() => {});
  } catch (error) {
    // Graceful fallback
  }
};

import AsyncStorage from "@react-native-async-storage/async-storage";
import * as SecureStore from "expo-secure-store";
import { Platform } from "react-native";

const memoryStore = new Map<string, string>();

const SECURE_KEYS = new Set([
  "access_token",
  "refresh_token",
  "auth_token",
  "user_token",
]);

function isSecureKey(key: string): boolean {
  return (
    SECURE_KEYS.has(key) ||
    key.toLowerCase().includes("token") ||
    key.toLowerCase().includes("refresh")
  );
}

function sanitizeKey(key: string): string {
  return (key || "key").replace(/[^a-zA-Z0-9._-]/g, "_");
}

export async function saveItem(key: string, value: string): Promise<void> {
  memoryStore.set(key, value);
  try {
    if (Platform.OS === "web") {
      localStorage.setItem(key, value);
    } else if (isSecureKey(key)) {
      try {
        await SecureStore.setItemAsync(sanitizeKey(key), value);
      } catch (secErr) {
        // Fallback to AsyncStorage if SecureStore/Keystore fails
        await AsyncStorage.setItem(key, value);
      }
    } else {
      await AsyncStorage.setItem(key, value);
    }
  } catch (error) {
    console.warn("[Storage] Error saving item:", key, error);
  }
}

export function getItemSync(key: string): string | null {
  return memoryStore.get(key) || null;
}

export async function getItem(key: string): Promise<string | null> {
  const inMem = memoryStore.get(key);
  if (inMem !== undefined) {
    return inMem;
  }

  try {
    if (Platform.OS === "web") {
      const val = localStorage.getItem(key);
      if (val !== null) memoryStore.set(key, val);
      return val;
    } else if (isSecureKey(key)) {
      try {
        const val = await SecureStore.getItemAsync(sanitizeKey(key));
        if (val !== null && val !== undefined) {
          memoryStore.set(key, val);
          return val;
        }
      } catch {
        // Fallback to AsyncStorage if SecureStore fails
      }
      try {
        const asyncVal = await AsyncStorage.getItem(key);
        if (asyncVal !== null && asyncVal !== undefined) {
          memoryStore.set(key, asyncVal);
          return asyncVal;
        }
      } catch {
        // Fallback to memory
      }
      return null;
    } else {
      try {
        const asyncVal = await AsyncStorage.getItem(key);
        if (asyncVal !== null && asyncVal !== undefined) {
          memoryStore.set(key, asyncVal);
          return asyncVal;
        }
      } catch {}
      // Fallback check legacy SecureStore in case key was saved there before
      try {
        const val = await SecureStore.getItemAsync(sanitizeKey(key));
        if (val !== null && val !== undefined) {
          memoryStore.set(key, val);
          return val;
        }
      } catch {}
      return null;
    }
  } catch (error) {
    console.warn("[Storage] Error getting item:", key, error);
    return null;
  }
}

export async function deleteItem(key: string): Promise<void> {
  memoryStore.delete(key);
  try {
    if (Platform.OS === "web") {
      localStorage.removeItem(key);
    } else {
      if (isSecureKey(key)) {
        try {
          await SecureStore.deleteItemAsync(sanitizeKey(key));
        } catch {
          // Ignore secure store delete failure
        }
      }
      try {
        await AsyncStorage.removeItem(key);
      } catch {
        // Ignore async storage delete failure
      }
    }
  } catch (error) {
    console.warn("[Storage] Error deleting item:", key, error);
  }
}

/**
 * Batch-preload multiple keys from SecureStore/AsyncStorage into memoryStore
 * in parallel. After this resolves, getItemSync() returns values instantly.
 */
let preloadPromise: Promise<void> | null = null;

export function preloadKeys(keys: string[]): Promise<void> {
  if (preloadPromise) return preloadPromise;

  preloadPromise = (async () => {
    if (Platform.OS === "web") return;

    await Promise.allSettled(
      keys.map(async (key) => {
        // Skip if already in memory
        if (memoryStore.has(key)) return;
        if (isSecureKey(key)) {
          try {
            const val = await SecureStore.getItemAsync(sanitizeKey(key));
            if (val !== null && val !== undefined) {
              memoryStore.set(key, val);
              return;
            }
          } catch {}
        }
        try {
          const asyncVal = await AsyncStorage.getItem(key);
          if (asyncVal !== null && asyncVal !== undefined) {
            memoryStore.set(key, asyncVal);
          }
        } catch {}
      }),
    );
  })();

  return preloadPromise;
}

// Auto-preload critical keys at module init time so context providers
// can access them synchronously as early as possible
preloadKeys([
  "smart-kirana-mobile-token",
  "smart-kirana-mobile-refresh",
  "smart-kirana-mobile-user",
  "sk_theme_mode",
  "sk_language",
]);
